async function fetchIndustrySolutionPages(): Promise<IndustrySolutionPage[]> {
  const supabase = createPublicClient();
  const { data: industries } = await supabase.from('industries').select('id, slug');
  const industrySlugById: Record<string, string> = Object.fromEntries((industries ?? []).map((i) => [i.id, i.slug]));

  const { data, error } = await supabase
    .from('industry_solution_pages')
    .select('*')
    .eq('is_active', true)
    .order('sort_order', { ascending: true });

  if (error || !data || data.length === 0) {
    if (error) console.error(`[getIndustrySolutionPages] failed: ${error.message} (code ${error.code})`);
    return SAMPLE_INDUSTRY_SOLUTION_PAGES;
  }

  return data
    .filter((row) => industrySlugById[row.industry_id])
    .map((row) => ({
      industrySlug: industrySlugById[row.industry_id],
      capabilityLabel: row.capability_label,
      slug: row.slug,
      title: row.title,
      tagline: row.tagline,
      overview: row.overview,
      overviewExtra: row.overview_extra,
      implementation: row.implementation ?? [],
      benefits: row.benefits ?? [],
      companies: row.companies ?? [],
      useCases: row.use_cases ?? [],
      faqs: row.faqs ?? [],
      primaryTech: row.primary_tech ?? [],
      seoTitle: row.seo_title ?? null,
      seoDescription: row.seo_description ?? null,
      targetKeywords: row.target_keywords ?? [],
    }));
}

export const getIndustrySolutionPages = unstable_cache(fetchIndustrySolutionPages, ['industry-solution-pages'], {
  tags: ['industry-solution-pages'],
  revalidate: 60,
});

export async function findIndustrySolutionPage(industrySlug: string, slug: string): Promise<IndustrySolutionPage | null> {
  const pages = await getIndustrySolutionPages();
  return pages.find((p) => p.industrySlug === industrySlug && p.slug === slug) ?? null;
}

/** Capability label -> deep-dive slug for one industry, built in one fetch so a capability-card grid can look up every card without N calls. */
export async function industrySolutionSlugMapForIndustry(industrySlug: string): Promise<Record<string, string>> {
  const pages = await getIndustrySolutionPages();
  return Object.fromEntries(
    pages.filter((p) => p.industrySlug === industrySlug).map((p) => [p.capabilityLabel, p.slug])
  );
}

export async function industrySolutionPagesForIndustry(industrySlug: string): Promise<IndustrySolutionPage[]> {
  const pages = await getIndustrySolutionPages();
  return pages.filter((p) => p.industrySlug === industrySlug);
}

export async function getAllIndustrySolutionParams(): Promise<{ industrySlug: string; slug: string }[]> {
  const pages = await getIndustrySolutionPages();
  return pages.map((p) => ({ industrySlug: p.industrySlug, slug: p.slug }));
}
